/**
 * Alerts: a message to an administrators' Discord channel when a game server stops answering
 * (after a grace period) and another one when it is back. The bot delivers the queued messages.
 */
import type { Express, RequestHandler } from 'express';
import { z } from 'zod';
import { db, EFFECTIVE_NAME, getSetting, setSetting } from './db.js';
import { gameLabel } from './games.js';
import { inMaintenance } from './maintenance.js';
import { claimDue, enqueueDelivery, registerKind, reportResult } from './deliveries.js';

db.exec(`
CREATE TABLE IF NOT EXISTS alert_state (
  server_id INTEGER PRIMARY KEY REFERENCES servers(id) ON DELETE CASCADE,
  down_since INTEGER NOT NULL,
  alerted INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS alerts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  kind TEXT NOT NULL,
  server_name TEXT NOT NULL DEFAULT '',
  channel_id TEXT NOT NULL,
  payload TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'queued',
  error TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  sent_at INTEGER
);
`);

const settings = () => ({
  enabled: getSetting('alerts_enabled') === '1',
  channelId: getSetting('alerts_channel') ?? '',
  afterMin: Math.min(120, Math.max(1, Number(getSetting('alerts_after_min')) || 3)),
  mention: (['none', 'here', 'everyone'].includes(getSetting('alerts_mention') ?? '') ? getSetting('alerts_mention') : 'none') as 'none' | 'here' | 'everyone',
});

const COLOR = { down: 0xf23f42, up: 0x23a55a, test: 0x5865f2 };

interface Payload {
  content: string;
  mention: 'none' | 'here' | 'everyone';
  embed: Record<string, unknown>;
}

function enqueue(kind: 'down' | 'up' | 'test', serverName: string, payload: Payload) {
  const s = settings();
  const now = Date.now();
  // the alerts table is the history shown in the panel; the delivery (attempts, backoff) lives in `deliveries`
  const r = db.prepare('INSERT INTO alerts (kind, server_name, channel_id, payload, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?)').run(kind, serverName, s.channelId, JSON.stringify(payload), now, now);
  enqueueDelivery({ kind: 'alert', refId: Number(r.lastInsertRowid), target: s.channelId, payload });
  db.prepare('DELETE FROM alerts WHERE created_at < ?').run(now - 14 * 24 * 3600 * 1000);
}

// the delivery queue reports its progress back into the history rows
registerKind('alert', {
  onState(refId, status, error, now) {
    // a failed attempt with a retry scheduled stays "queued" (with the last error); only a dead delivery is an error
    const st = status === 'sent' ? 'sent' : status === 'dead' ? 'error' : status === 'sending' ? 'sending' : 'queued';
    db.prepare("UPDATE alerts SET status = ?, error = ?, sent_at = CASE WHEN ? = 'sent' THEN ? ELSE sent_at END, updated_at = ? WHERE id = ?").run(st, error, st, now, now, refId);
  },
});

// alerts queued by an older version (before the delivery queue existed) are moved into it once
for (const a of db.prepare("SELECT id, channel_id, payload FROM alerts WHERE status IN ('queued','sending')").all() as { id: number; channel_id: string; payload: string }[]) {
  if (!db.prepare("SELECT 1 FROM deliveries WHERE kind = 'alert' AND ref_id = ?").get(a.id)) {
    enqueueDelivery({ kind: 'alert', refId: a.id, target: a.channel_id, payload: JSON.parse(a.payload) as unknown });
  }
}

const minutes = (ms: number) => Math.max(1, Math.round(ms / 60_000));
const human = (min: number) => (min < 60 ? `${min} мин` : `${Math.floor(min / 60)} ч ${min % 60} мин`);

/** Called after every poll of a server. */
export function trackAlerts(serverId: number, online: boolean, error: string | null): void {
  const s = settings();
  if (!s.enabled || !s.channelId) {
    db.prepare('DELETE FROM alert_state WHERE server_id = ?').run(serverId);
    return;
  }
  const now = Date.now();
  const st = db.prepare('SELECT down_since, alerted FROM alert_state WHERE server_id = ?').get(serverId) as { down_since: number; alerted: number } | undefined;
  const info = () =>
    db
      .prepare(`SELECT ${EFFECTIVE_NAME} AS n, s.game, s.display_address, s.host, s.port FROM servers s LEFT JOIN status st ON st.server_id = s.id WHERE s.id = ?`)
      .get(serverId) as { n: string; game: string; display_address: string; host: string; port: number } | undefined;

  // maintenance window: nothing is sent. A not yet alerted outage is forgotten, so that a real outage that is still
  // going on when the window ends starts counting from the end of the window; an already alerted one stays as it is.
  if (inMaintenance(serverId, now)) {
    if (st && !st.alerted) db.prepare('DELETE FROM alert_state WHERE server_id = ?').run(serverId);
    return;
  }

  if (online) {
    if (st) {
      db.prepare('DELETE FROM alert_state WHERE server_id = ?').run(serverId);
      if (st.alerted) {
        const i = info();
        if (i) {
          enqueue('up', i.n, {
            content: '',
            mention: 'none',
            embed: {
              title: `🟢 ${i.n} снова в сети`,
              description: `📍 \`${i.display_address || `${i.host}:${i.port}`}\`\nПростой: **${human(minutes(now - st.down_since))}**`,
              color: COLOR.up,
              author: { name: `🎮 ${gameLabel(i.game)}` },
              footer: { text: 'CoreGSM · оповещение' },
              timestamp: new Date(now).toISOString(),
            },
          });
        }
      }
    }
    return;
  }

  if (!st) {
    db.prepare('INSERT INTO alert_state (server_id, down_since, alerted) VALUES (?, ?, 0)').run(serverId, now);
    return;
  }
  if (!st.alerted && now - st.down_since >= s.afterMin * 60_000) {
    const i = info();
    db.prepare('UPDATE alert_state SET alerted = 1 WHERE server_id = ?').run(serverId);
    if (!i) return;
    enqueue('down', i.n, {
      content: s.mention === 'everyone' ? '@everyone' : s.mention === 'here' ? '@here' : '',
      mention: s.mention,
      embed: {
        title: `🔴 ${i.n} недоступен`,
        description: `📍 \`${i.display_address || `${i.host}:${i.port}`}\`\nСервер не отвечает уже **${human(minutes(now - st.down_since))}**${error ? `\n⚠️ ${error.slice(0, 300)}` : ''}`,
        color: COLOR.down,
        author: { name: `🎮 ${gameLabel(i.game)}` },
        footer: { text: 'CoreGSM · оповещение' },
        timestamp: new Date(now).toISOString(),
      },
    });
  }
}

export function registerAlerts(deps: {
  app: Express;
  admin: RequestHandler;
  internal: RequestHandler;
  channelInfo: (id: string) => { channelName: string | null; guildName: string | null };
}): void {
  const { app, admin, internal, channelInfo } = deps;

  const payload = () => {
    const s = settings();
    const ch = s.channelId ? channelInfo(s.channelId) : { channelName: null, guildName: null };
    const recent = db.prepare('SELECT id, kind, server_name, status, error, created_at, sent_at FROM alerts ORDER BY id DESC LIMIT 30').all() as {
      id: number;
      kind: string;
      server_name: string;
      status: string;
      error: string | null;
      created_at: number;
      sent_at: number | null;
    }[];
    return {
      ...s,
      channelName: ch.channelName,
      guildName: ch.guildName,
      recent: recent.map((r) => ({ id: r.id, kind: r.kind, serverName: r.server_name, status: r.status, error: r.error, createdAt: r.created_at, sentAt: r.sent_at })),
    };
  };

  app.get('/api/alerts', admin, (_req, res) => res.json(payload()));

  app.put('/api/alerts', admin, (req, res) => {
    const b = z
      .object({
        enabled: z.boolean().optional(),
        channelId: z.string().regex(/^(\d{15,25})?$/, 'Неверный ID канала').optional(),
        afterMin: z.number().int().min(1).max(120).optional(),
        mention: z.enum(['none', 'here', 'everyone']).optional(),
      })
      .safeParse(req.body);
    if (!b.success) return res.status(400).json({ error: b.error.issues[0]?.message ?? 'Проверьте поля' });
    if (b.data.enabled !== undefined) {
      if (b.data.enabled && !(b.data.channelId ?? getSetting('alerts_channel'))) return res.status(400).json({ error: 'Сначала выберите канал для оповещений' });
      setSetting('alerts_enabled', b.data.enabled ? '1' : '0');
    }
    if (b.data.channelId !== undefined) setSetting('alerts_channel', b.data.channelId);
    if (b.data.afterMin !== undefined) setSetting('alerts_after_min', String(b.data.afterMin));
    if (b.data.mention !== undefined) setSetting('alerts_mention', b.data.mention);
    res.json(payload());
  });

  app.post('/api/alerts/test', admin, (_req, res) => {
    const s = settings();
    if (!s.channelId) return res.status(400).json({ error: 'Сначала выберите канал для оповещений' });
    enqueue('test', 'Проверка', {
      content: '',
      mention: 'none',
      embed: {
        title: '🔔 Проверка оповещений',
        description: 'Если вы видите это сообщение, оповещения о недоступности серверов настроены верно.',
        color: COLOR.test,
        footer: { text: 'CoreGSM · оповещение' },
        timestamp: new Date().toISOString(),
      },
    });
    res.json(payload());
  });

  // ----- the bot (compatibility shim: the bot now uses /internal/deliveries/*; ids here are delivery ids) -----
  app.get('/internal/alerts/pending', internal, (_req, res) => {
    res.json(claimDue(['alert']).map((d) => ({ id: d.id, channelId: d.target, payload: d.payload as Payload })));
  });

  app.patch('/internal/alerts/:id', internal, (req, res) => {
    const b = z.object({ status: z.enum(['sent', 'error']), error: z.string().max(300).nullable().optional() }).safeParse(req.body);
    if (!b.success) return res.status(400).json({ error: 'bad body' });
    reportResult(Number(req.params.id), b.data.status === 'sent' ? { ok: true } : { ok: false, error: b.data.error ?? 'Ошибка отправки' });
    res.json({ ok: true });
  });
}
__COREGSM_EOF__
  mkdir -p "$APP_DIR/core-backend/src"
  cat > "$APP_DIR/core-backend/src/auth.ts" << '__COREGSM_EOF__'
/** Sessions, roles and the access middleware; login rate limits and lockout. */
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import crypto from 'node:crypto';
import type { NextFunction, Request, Response } from 'express';
import { INTERNAL_TOKEN, JWT_SECRET } from './config.js';
import { db, getSetting } from './db.js';
import { safeEqual } from './http.js';
import { guardDelete, guardGet, guardSet } from './loginGuard.js';
import { uaLabel } from './profile.js';
import { readCookie, SESSION_COOKIE } from './security.js';

// a real bcrypt hash (cost 12) to compare against when the login does not exist: the response time stays the same
export const DUMMY_HASH = bcrypt.hashSync(crypto.randomBytes(8).toString('hex'), 12);

// ---------- auth ----------
export type Role = 'admin' | 'moderator' | 'player';
export interface AuthedRequest extends Request {
  user?: { id: number; username: string; role: Role; sid?: string };
}

/** The signed-in user (checked against the database, so a deleted or demoted account loses access at once). */
export function userFromToken(token: string): { id: number; username: string; role: Role; sid: string } | null {
  if (!token) return null;
  try {
    const p = jwt.verify(token, JWT_SECRET, { algorithms: ['HS256'] }) as { sub: string; sid?: string };
    // a token without a session id predates sessions: sign in again
    if (!p.sid) return null;
    const u = db.prepare("SELECT id, username, role FROM users WHERE id = ? AND status = 'active'").get(Number(p.sub)) as { id: number; username: string; role: Role } | undefined;
    if (!u) return null;
    // an ended session (revoked from the profile) stops working at once
    if (!db.prepare('SELECT 1 FROM sessions WHERE id = ? AND user_id = ?').get(p.sid, u.id)) return null;
    const now = Date.now();
    if (now - (lastSeen.get(p.sid) ?? 0) > 60_000) {
      lastSeen.set(p.sid, now);
      db.prepare('UPDATE sessions SET last_seen = ? WHERE id = ?').run(now, p.sid);
    }
    return { ...u, sid: p.sid };
  } catch {
    return null;
  }
}
export const lastSeen = new Map<string, number>();

/** Bearer header first (API clients, the bot), then the HttpOnly session cookie of the web panel. */
export function loadUser(req: Request) {
  const h = req.headers.authorization ?? '';
  return userFromToken(h.startsWith('Bearer ') ? h.slice(7) : '') ?? userFromToken(readCookie(req, SESSION_COOKIE));
}

/** Starts a session and returns the signed token for it. */
export function issueToken(u: { id: number; username: string }, req: Request): string {
  const sid = crypto.randomBytes(12).toString('hex');
  const now = Date.now();
  db.prepare('INSERT INTO sessions (id, user_id, created_at, last_seen, ip, ua) VALUES (?, ?, ?, ?, ?, ?)').run(sid, u.id, now, now, (req.ip ?? '').slice(0, 64), uaLabel(req.headers['user-agent']));
  return jwt.sign({ username: u.username, sid }, JWT_SECRET, { subject: String(u.id), expiresIn: '7d', algorithm: 'HS256' });
}
setInterval(() => db.prepare('DELETE FROM sessions WHERE created_at < ?').run(Date.now() - 8 * 24 * 3600 * 1000), 3600_000).unref();

export const isAdmin = (req: Request) => (req as AuthedRequest).user?.role === 'admin';
export const isStaff = (req: Request) => {
  const r = (req as AuthedRequest).user?.role;
  return r === 'admin' || r === 'moderator';
};
export const flag = (key: string, fallback: boolean) => {
  const v = getSetting(key);
  return v === null ? fallback : v === '1';
};
export const publicPanel = () => flag('public_panel', true);
export const registrationOpen = () => flag('registration_open', true);

/** any signed-in user */
export function auth(req: AuthedRequest, res: Response, next: NextFunction) {
  const u = loadUser(req);
  if (!u) return void res.status(401).json({ error: 'Требуется вход' });
  req.user = u;
  next();
}
/** administrators only */
export function admin(req: AuthedRequest, res: Response, next: NextFunction) {
  const u = loadUser(req);
  if (!u) return void res.status(401).json({ error: 'Требуется вход' });
  if (u.role !== 'admin') return void res.status(403).json({ error: 'Это действие доступно только администратору' });
  req.user = u;
  next();
}
/** administrators and moderators (news and the Discord channel list) */
export function staff(req: AuthedRequest, res: Response, next: NextFunction) {
  const u = loadUser(req);
  if (!u) return void res.status(401).json({ error: 'Требуется вход' });
  if (u.role !== 'admin' && u.role !== 'moderator') return void res.status(403).json({ error: 'Это действие доступно администратору и модератору' });
  req.user = u;
  next();
}
/** viewing: open to everyone while the panel is public, otherwise requires a sign-in */
export function viewer(req: AuthedRequest, res: Response, next: NextFunction) {
  const u = loadUser(req);
  if (u) req.user = u;
  if (!u && !publicPanel()) return void res.status(401).json({ error: 'Требуется вход' });
  next();
}

// ---------- lockout after wrong passwords for one login from one address (kept in SQLite, see loginGuard.ts) ----------
export const LOCK_AFTER = 5;
const accountKey = (ip: string | undefined, username: string) => `${ip ?? 'x'}|${username.toLowerCase()}`;

/** seconds until this login may be tried again from this address (0 = not locked) */
export function accountLockRemaining(ip: string | undefined, username: string): number {
  const f = guardGet<{ n: number; until: number }>('account', accountKey(ip, username));
  return f && f.until > Date.now() ? Math.ceil((f.until - Date.now()) / 1000) : 0;
}

/** counts a wrong password; returns how many tries are left before the lockout (0 = locked now) */
export function accountLoginFailed(ip: string | undefined, username: string): number {
  const key = accountKey(ip, username);
  const now = Date.now();
  const f = guardGet<{ n: number; until: number }>('account', key) ?? { n: 0, until: 0 };
  f.n++;
  // 30 s, 1 min, 2 min ... up to 15 minutes
  if (f.n >= LOCK_AFTER) f.until = now + Math.min(15 * 60_000, 30_000 * 2 ** (f.n - LOCK_AFTER));
  // failures below the limit are forgotten 10 minutes after the last one; a lockout is remembered for an hour
  // after it ends, so the next one is longer
  guardSet('account', key, f, f.until ? f.until + 3600_000 : now + 10 * 60_000);
  return f.n >= LOCK_AFTER ? 0 : LOCK_AFTER - f.n;
}

export const accountLoginOk = (ip: string | undefined, username: string) => guardDelete('account', accountKey(ip, username));

/** a lighter per-address limit for public lookups: `max` requests per minute */
export function rateLimit(max: number) {
  const hits = new Map<string, { n: number; reset: number }>();
  setInterval(() => { for (const [k, v] of hits) if (v.reset < Date.now()) hits.delete(k); }, 60_000).unref();
  return (req: Request, res: Response, next: NextFunction) => {
    const key = req.ip ?? 'x';
    const now = Date.now();
    const h = hits.get(key);
    if (!h || h.reset <= now) hits.set(key, { n: 1, reset: now + 60_000 });
    else if (++h.n > max) {
      const retryAfter = Math.max(1, Math.ceil((h.reset - now) / 1000));
      res.setHeader('Retry-After', String(retryAfter));
      return void res.status(429).json({ error: 'Слишком много запросов. Подождите минуту.', retryAfter });
    }
    next();
  };
}

/** sign-in, registration and setup: at most 10 attempts per address in 10 minutes (a success clears the count) */
export function loginLimiter(req: Request, res: Response, next: NextFunction) {
  const key = req.ip ?? 'x';
  const now = Date.now();
  const a = guardGet<{ n: number; reset: number }>('attempts', key);
  if (a && a.reset > now && a.n >= 10) {
    const retryAfter = Math.max(1, Math.ceil((a.reset - now) / 1000));
    res.setHeader('Retry-After', String(retryAfter));
    res.status(429).json({ error: 'Слишком много попыток. Подождите 10 минут.', retryAfter });
    return;
  }
  const next_ = !a || a.reset <= now ? { n: 1, reset: now + 10 * 60 * 1000 } : { n: a.n + 1, reset: a.reset };
  guardSet('attempts', key, next_, next_.reset);
  next();
}
export const resetAttempts = (ip: string | undefined) => guardDelete('attempts', ip ?? 'x');

// ---------- the signed-in user: profile, password, sessions, Discord account ----------
export interface UserFull { id: number; username: string; role: Role; password_hash: string; no_password: number; discord_id: string | null; discord_name: string | null; discord_avatar: string | null; email?: string | null; email_verified?: number }
export const avatarUrl = (u: UserFull) => (u.discord_id && u.discord_avatar ? `https://cdn.discordapp.com/avatars/${u.discord_id}/${u.discord_avatar}.png?size=64` : null);

// ---------- internal (bot only, not exposed by nginx) ----------
export function internal(req: Request, res: Response, next: NextFunction) {
  if (safeEqual(String(req.headers['x-internal-token'] ?? ''), INTERNAL_TOKEN)) return next();
  res.status(403).json({ error: 'forbidden' });
}
