{
  "name": "core-bot",
  "version": "1.0.0",
  "lockfileVersion": 3,
  "requires": true,
  "packages": {
    "": {
      "name": "core-bot",
      "version": "1.0.0",
      "dependencies": {
        "discord.js": "^14.16.3",
        "fetch-socks": "^1.3.2",
        "https-proxy-agent": "^7.0.6",
        "socks-proxy-agent": "^8.0.5",
